
(async () => {
  const HIT_GZ = "";
  const SOURCE_SHA256 = "228ab098c4722714c3beefd383b176108d8fec61dce296db752dd4a9089b0d7d";
  const status = document.getElementById("status");

  const sleep = ms => new Promise(r => setTimeout(r,ms));

  async function gunzipB64(s) {
    const bin=atob(s), raw=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) raw[i]=bin.charCodeAt(i);
    const ds=new DecompressionStream("gzip");
    return await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer();
  }

  async function importFirst(urls) {
    let last;
    for(const u of urls) {
      try { return await window.__LOCAL_IMPORT(u); }
      catch(e) { last=e; }
    }
    throw last || new Error("Falha ao carregar módulos da animação.");
  }

  async function waitGame() {
    for(let i=0;i<1000;i++) {
      const g=window.gameReview;
      if(
        g?.trueFirstPerson?.model &&
        g?.trueFirstPerson?.visibleRoot &&
        g?.trueFirstPerson?.eyeSocket &&
        g?.trueFirstPerson?.bones?.head &&
        g?.camera
      ) return g;
      await sleep(20);
    }
    throw new Error("Rig/câmera do jogador não ficaram disponíveis.");
  }

  function prepareReactionClip(source) {
    const clip=source.clone();

    // ONLY animation data from the uploaded FBX.
    // Keep every body/head rotation so the full character reacts.
    // Do not accept root translation or scale, because the current game
    // controller still owns the player's world position.
    clip.tracks=clip.tracks.filter(track=>{
      if(/\.scale$/i.test(track.name)) return false;
      if(/\.position$/i.test(track.name)) return false;

      if(/\.quaternion$/i.test(track.name)) {
        // Existing physical grips remain responsible for fingers, preventing
        // the axe/torch from visually falling out of the hands.
        if(/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(track.name)) return false;
        return true;
      }
      return false;
    });

    clip.name="Light Hit To Head - FULL BODY";
    clip.resetDuration();
    return clip;
  }

  try {
    const game=await waitGame();
    const tfp=game.trueFirstPerson;

    const [THREE,loaderMod,buffer]=await Promise.all([
      importFirst([
        window.FLORESTA_MODULES.three,
        window.FLORESTA_MODULES.three
      ]),
      importFirst([
        window.FLORESTA_MODULES.FBXLoader,
        window.FLORESTA_MODULES.FBXLoader
      ]),
      gunzipB64(HIT_GZ)
    ]);

    const {FBXLoader}=loaderMod;
    const parsed=new FBXLoader().parse(buffer,"");

    if(!parsed.animations?.length) {
      throw new Error("Light Hit To Head.fbx não contém animação.");
    }

    const hitClip=prepareReactionClip(parsed.animations[0]);
    if(!hitClip.tracks.length) {
      throw new Error("Nenhuma track compatível com o rig atual.");
    }

    // Dedicated mixer runs AFTER the normal full-body controller and AFTER
    // the player's axe-attack mixer. Therefore the damage reaction actually
    // owns the body for the duration of the supplied animation.
    const mixer=new THREE.AnimationMixer(tfp.model);
    const action=mixer.clipAction(hitClip,tfp.model);
    action.setLoop(THREE.LoopOnce,1);
    action.clampWhenFinished=true;
    action.enabled=true;
    action.setEffectiveWeight(1);
    action.setEffectiveTimeScale(1);

    let active=false;
    let lastFrame=performance.now();
    let finishTimer=null;

    const headWorld=new THREE.Quaternion();
    const camWorld=new THREE.Quaternion();
    const cameraFromHead=new THREE.Quaternion();
    const desiredCameraWorld=new THREE.Quaternion();
    const parentWorld=new THREE.Quaternion();
    const eyeWorld=new THREE.Vector3();
    const eyeLocal=new THREE.Vector3();
    const torchSocketWorld=new THREE.Vector3();
    const bodyYawQ=new THREE.Quaternion();
    const torchOffset=new THREE.Vector3(0,.06*.65,0);

    function captureCameraRelation() {
      tfp.visibleRoot.updateMatrixWorld(true);
      tfp.bones.head.getWorldQuaternion(headWorld);
      game.camera.getWorldQuaternion(camWorld);

      // cameraWorld = headWorld * cameraFromHead
      cameraFromHead.copy(headWorld).invert().multiply(camWorld);
    }

    function forceCameraToAnimatedHead() {
      tfp.visibleRoot.updateMatrixWorld(true);

      // Position follows the actual animated eye socket.
      tfp.eyeSocket.getWorldPosition(eyeWorld);

      if(game.camera.parent) {
        eyeLocal.copy(eyeWorld);
        game.camera.parent.worldToLocal(eyeLocal);
        game.camera.position.copy(eyeLocal);
      } else {
        game.camera.position.copy(eyeWorld);
      }

      // Orientation follows the animated head as well, preserving the exact
      // pre-hit relationship between the player's eyes and head.
      tfp.bones.head.getWorldQuaternion(headWorld);
      desiredCameraWorld.copy(headWorld).multiply(cameraFromHead);

      if(game.camera.parent) {
        game.camera.parent.getWorldQuaternion(parentWorld);
        game.camera.quaternion.copy(parentWorld.invert().multiply(desiredCameraWorld));
      } else {
        game.camera.quaternion.copy(desiredCameraWorld);
      }

      game.camera.updateMatrixWorld(true);
    }

    function resyncHeldItems() {
      tfp.visibleRoot.updateMatrixWorld(true);

      // Existing axe, existing hand, existing grip.
      // No weapon or hand is imported from the hit FBX.
      window.gameRightHand?.sync?.();

      // Existing torch follows the animated left hand socket.
      if(game.torchRoot && game.isEquipped?.()) {
        tfp.socket.getWorldPosition(torchSocketWorld);
        bodyYawQ.setFromAxisAngle(
          new THREE.Vector3(0,1,0),
          game.player.bodyYaw ?? game.player.yaw
        );
        game.torchRoot.position.copy(torchSocketWorld).sub(
          torchOffset.clone().applyQuaternion(bodyYawQ)
        );
      }
    }

    function finishReaction() {
      action.stop();
      mixer.stopAllAction();
      active=false;
      window.gamePlayerHit.active=false;

      // The existing controller regains the body/camera on the next frame.
      window.gameRightHand?.sync?.();

      if(status && window.gameZombie?.active) {
        status.textContent="Você recuperou a postura";
      }
    }

    function playReaction(detail={}) {
      // If another hit lands while the reaction is already playing,
      // restart the exact supplied animation from its beginning.
      clearTimeout(finishTimer);

      captureCameraRelation();

      active=true;
      window.gamePlayerHit.active=true;

      action.stop();
      action.reset();
      action.enabled=true;
      action.setEffectiveWeight(1);
      action.setEffectiveTimeScale(1);
      action.play();

      if(status) {
        const hp=detail.playerHp;
        status.textContent=
          hp==null ? "Você recebeu um golpe" : `Você recebeu um golpe • vida ${Math.round(hp)}`;
      }

      finishTimer=setTimeout(
        finishReaction,
        Math.max(180,hitClip.duration*1000+35)
      );
    }

    // Wrap the existing update chain. The hit clip is evaluated LAST.
    const previousUpdate=window.__updateAnimatedAvatar;
    window.__updateAnimatedAvatar=(...args)=>{
      previousUpdate?.(...args);

      const now=performance.now();
      const dt=Math.min(.05,Math.max(0,(now-lastFrame)/1000));
      lastFrame=now;

      if(active) {
        mixer.update(dt);

        // After animation has rotated the whole rig:
        // 1) keep current items in the animated hands
        // 2) put camera at animated eyes
        // 3) rotate camera with animated head
        resyncHeldItems();
        forceCameraToAnimatedHead();
      }
    };

    window.addEventListener("game:player-damaged",e=>{
      playReaction(e.detail || {});
    });

    window.gamePlayerHit={
      active:false,
      play:playReaction,
      get duration(){return hitClip.duration;},
      get clipName(){return hitClip.name;},
      get trackCount(){return hitClip.tracks.length;},
      source:"Light Hit To Head.fbx",
      sourceSha256:SOURCE_SHA256,
      mode:"full-body-camera-follows-head"
    };

    if(status) {
      status.textContent=
        `Reação de dano pronta • ${hitClip.tracks.length} tracks • câmera acompanha cabeça`;
    }
  } catch(err) {
    console.error("Reação de dano do jogador:",err);
    if(status) {
      status.textContent+=" • reação de dano indisponível: "+String(err?.message||err);
    }
  }
})();
